package com.ml.tblandroidtxt;
import org.junit.Test;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
public class EditorialModelSceneMapperTest {
 @Test public void acceptsOnlyMonotonicFullDraftCoverage() throws Exception {EditorialSceneSegmenter.Plan plan=EditorialSceneSegmenter.split("r1\n\nr2\n",256);AtomicInteger calls=new AtomicInteger();EditorialModelSceneMapper.Result result=EditorialModelSceneMapper.map(new AppSettings(),plan,"d1\nd2\n",(s,p,id)->{OpenAICompatibleClient.ChatResult r=new OpenAICompatibleClient.ChatResult();r.content="{\"sceneId\":\"scene-001\",\"rawStart\":\"p000001\",\"rawEnd\":\"p000003\",\"draftStart\":\"d000001\",\"draftEnd\":\"d000002\",\"status\":\"ALIGNED\"}";calls.incrementAndGet();return r;},"map");assertEquals(1,calls.get());assertEquals("d1\nd2\n",result.pairs.get(0).draft);}
 @Test public void rejectsSkippedDraftAnchor() {try{EditorialSceneSegmenter.Plan plan=EditorialSceneSegmenter.split("raw\n",256);EditorialModelSceneMapper.map(new AppSettings(),plan,"a\nb\n",(s,p,id)->{OpenAICompatibleClient.ChatResult r=new OpenAICompatibleClient.ChatResult();r.content="{\"sceneId\":\"scene-001\",\"rawStart\":\"p000001\",\"rawEnd\":\"p000001\",\"draftStart\":\"d000002\",\"draftEnd\":\"d000002\",\"status\":\"ALIGNED\"}";return r;},"map");fail();}catch(Exception expected){assertTrue(expected.getMessage().contains("Non-monotonic"));}}
 @Test public void rebuildsPairsFromValidatedEvidence() throws Exception{EditorialSceneSegmenter.Plan plan=EditorialSceneSegmenter.split("raw\n",256);String evidence="[{\"sceneId\":\"scene-001\",\"rawStart\":\"p000001\",\"rawEnd\":\"p000001\",\"draftStart\":\"d000001\",\"draftEnd\":\"d000002\",\"status\":\"ALIGNED\"}]";assertEquals("a\nb\n",EditorialModelSceneMapper.fromEvidence(plan,"a\nb\n",evidence).get(0).draft);}
}
